// Port of jumpnrun/levelgen/generator.py: procedural levels with difficulty tiers, reproducible from (tier, seed).
// Every random call happens in the same order as in Python, so the same seed gives the same level text
// (tests/generator.test.ts compares against levels generated by Python).

import { ROWS } from "../core/constants";
import { Level } from "../core/level";
import catalogJson from "./jump_catalog.json";
import { PyRandom, range } from "./pyrandom";

export const GROUND = ROWS - 1;
export const HIGHEST_SURFACE = 5;
const TOP_ROW = 3;

