const V10_EXTRA: Partial<TierConfig> = { channels: 0.6, pipes: 0.4, pyramids: 0.4, bridges: 0.4, groups: 0.4, channel_end: 0.15 };
export const NUM_TIERS = TIERS.length;

export type Cell = [number, number];

export interface GeneratedLevel extends Level {
  waypoints: Cell[];
  tier: number;
  variant: string;
  needsPath: boolean;
  buildingBlocks: Record<string, number>;
}

class Builder {
  columns: string[][] = [];
  surface = GROUND;
  style = new Map<string, number>();
  stats: Record<string, number> = {};
  waypoints: Cell[] = [];
  variant = "v9";
  needsPath = false;

  constructor(readonly rng: PyRandom) {}

  /** Python list indexing: negative indices count from the end. */
  col(i: number): string[] {
    return this.columns[i < 0 ? this.columns.length + i : i];
  }

  set(c: number, r: number, ch: string): void {
    const col = this.col(c);
    col[r < 0 ? ROWS + r : r] = ch;
  }

  get(c: number, r: number): string {
    return this.col(c)[r < 0 ? ROWS + r : r];
  }

  column(surface: number | null = null, extra: [number, string][] | null = null): string[] {
    const col = new Array<string>(ROWS).fill(" ");
    if (surface !== null) for (let r = surface; r < ROWS; r++) col[r] = "B";
    for (const [row, ch] of extra ?? []) col[row < 0 ? ROWS + row : row] = ch;
    this.columns.push(col);
    return col;
  }

  flat(n: number, enemy = false): void {
    const start = this.columns.length;
    for (let i = 0; i < n; i++) this.column(this.surface);
    if (enemy && n >= 3) this.set(start + Math.floor(n / 2), this.surface - 1, "E");
  }

  gap(width: number): void {
    for (let i = 0; i < width; i++) this.column(null);
  }

  rise(): boolean {
    if (this.surface - 1 < HIGHEST_SURFACE) return false;
    this.surface -= 1;
    return true;
  }

  drop(rows: number): void {
    this.surface = Math.min(GROUND, this.surface + rows);
  }
}

const block = (row: number | null): [number, string][] | null => (row !== null ? [[row, "B"]] : null);

function style(rng: PyRandom, cfg: TierConfig, variant: string): Map<string, number> {
  const base: [string, number][] = [
    ["flat", 1.0],
    ["gap", cfg.max_gap ? 1.2 : 0.0],
    ["step", cfg.steps ? 1.0 : 0.0],
    ["valley", cfg.valleys],
    ["platforms", cfg.platforms],
    ["climb", cfg.climbs],
    ["high_road", cfg.high_roads],
    ["stones", cfg.stones],
    ["tunnel", cfg.tunnels],
    ["shaft", cfg.shafts],
    ["ceiling", cfg.ceilings],
    ["two_routes", cfg.two_routes],
    ["rain_stairs", cfg.rain_stairs],
    ["chain", cfg.chains],
    ["trench", cfg.trenches],
    ["jump_seq", cfg.jumps],
    ["enemy_ramp", cfg.enemy_ramps],
    ["bait_fork", cfg.bait_forks],
  ];
  if (variant === "v10") {
    base.push(["channel", cfg.channels], ["pipes", cfg.pipes], ["pyramid", cfg.pyramids], ["bridge", cfg.bridges],
      ["group", cfg.groups]);
  }
  const out = new Map<string, number>();
  for (const [kind, w] of base) if (w > 0) out.set(kind, w * (0.3 + rng.gammavariate(1.0, 1.0)));
  return out;
}

function segment(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  const s = b.surface;
  const allowed: Record<string, boolean> = {
    valley: s <= GROUND - 1,
    high_road: s === GROUND,
    two_routes: s === GROUND,
    shaft: s >= HIGHEST_SURFACE + 3,
    tunnel: s >= 4,
    ceiling: s >= 5,
    rain_stairs: s >= GROUND - 1,
    trench: s >= 6,
    enemy_ramp: s >= HIGHEST_SURFACE + 3,
    bait_fork: s === GROUND,
    channel: s === GROUND,
    pipes: s >= HIGHEST_SURFACE + 2,
    pyramid: s >= HIGHEST_SURFACE + 4,
    bridge: s >= HIGHEST_SURFACE + 3,
  };
  const choices = [...b.style].filter(([kind]) => allowed[kind] ?? true);
  const kind = rng.choiceWeighted(choices.map((c) => c[0]), choices.map((c) => c[1]));
  b.stats[kind] = (b.stats[kind] ?? 0) + 1;

  switch (kind) {
    case "flat": {
      const n = rng.randint(2, 6);
      b.flat(n, rng.random() < cfg.free_enemies);
      break;
    }
    case "gap": {
      const width = rng.randint(1, cfg.max_gap);
      const drop = width === 3 || (cfg.steps && rng.random() < 0.3) ? rng.randint(1, cfg.max_drop) : 0;
      b.gap(width);
      b.drop(drop);
      if (width === 1 && cfg.steps && rng.random() < 0.3) b.rise();
      b.flat(rng.randint(2, 4));
      break;
    }
    case "step": {
      if (rng.random() < 0.55 && b.rise()) {
        b.flat(rng.randint(2, 4));
        if (rng.random() < 0.3 && b.rise()) b.flat(rng.randint(2, 3));
      } else {
        b.drop(rng.randint(1, cfg.max_drop));
        b.flat(rng.randint(2, 4));
      }
      break;
    }
    case "valley": {
      const depth = rng.randint(1, Math.min(2, GROUND - b.surface));
      const top = b.surface;
      b.drop(depth);
      const width = rng.randint(5, 8);
      const start = b.columns.length;
      b.flat(width, true);
      if (cfg.enemy_groups && rng.random() < 0.5) {
        for (const offset of rng.sample(range(1, width - 1), Math.min(2, width - 2))) {
          b.set(start + offset, b.surface - 1, "E");
        }
      }
      if (cfg.rain && rng.random() < cfg.rain) {
        const c = start + rng.randrange(width);
        b.set(c, rng.randint(1, 3), "E");
      }
      for (let i = 0; i < depth; i++) {
        b.rise();
        b.flat(2);
      }
      b.surface = top;
      break;
    }
    case "climb": climb(b, cfg); break;
    case "high_road": highRoad(b, cfg); break;
    case "tunnel": tunnel(b, cfg); break;
    case "shaft": shaft(b, cfg); break;
    case "ceiling": ceiling(b, cfg); break;
    case "two_routes": twoRoutes(b, cfg); break;
    case "rain_stairs": rainStairs(b); break;
    case "chain": chain(b); break;
    case "trench": trench(b); break;
    case "jump_seq": jumpSequence(b, cfg); break;
    case "enemy_ramp": enemyRamp(b, cfg); break;
    case "bait_fork":
      if (b.variant === "v9") baitFork(b, cfg);
      else forkV10(b, cfg);
      break;
    case "channel": channel(b, cfg); break;
    case "pipes": pipes(b, cfg); break;
    case "pyramid": pyramid(b, cfg); break;
    case "bridge": bridge(b); break;
    case "group": {
      b.flat(2);
      const start = b.columns.length;
      const width = rng.randint(6, 9);
      b.flat(width);
      const k = rng.randint(2, 3);
      for (const offset of rng.sample(range(1, width - 1), k)) b.set(start + offset, b.surface - 1, "E");
      b.flat(2);
      break;
    }
    case "stones": {
      let row = Math.max(HIGHEST_SURFACE, b.surface - rng.randint(0, 1));
      b.flat(1);
      b.gap(2);
      const n = rng.randint(2, 5);
      for (let i = 0; i < n; i++) {
        if (i && cfg.max_drop >= 4 && rng.random() < 0.5) {
          row = Math.max(4, Math.min(GROUND - 1, row + rng.choice([-1, 1])));
        }
        b.column(null, block(row));
        b.gap(3);
      }
      b.surface = Math.max(row, Math.min(GROUND, row + rng.randint(0, 2)));
      b.flat(rng.randint(2, 4));
      break;
    }
    case "platforms": {
      let levelRow = b.surface;
      b.flat(1);
      const hops = rng.randint(1, 3);
      for (let h = 0; h < hops; h++) {
        b.gap(rng.randint(1, 2));
        const change = rng.choice([-1, 0, 0, 1]);
        levelRow = Math.max(HIGHEST_SURFACE, Math.min(GROUND - 1, levelRow + change));
        const width = rng.randint(2, 3);
        const start = b.columns.length;
        for (let i = 0; i < width; i++) b.column(null, block(levelRow));
        if (cfg.platform_enemies && width === 3 && rng.random() < 0.35) b.set(start + 1, levelRow - 1, "E");
      }
      b.gap(rng.randint(1, 2));
      b.surface = Math.max(levelRow, Math.min(GROUND, levelRow + rng.randint(0, 1)));
      b.flat(rng.randint(2, 4));
      break;
    }
    default:
      throw new Error(`unknown building block ${kind}`);
  }
}

type ClimbItem = ["gap", number] | ["block", number, number] | ["enemy_on_last", number];

function climb(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  const startSurface = b.surface;
  b.flat(2);
  let row = startSurface;
  const items: ClimbItem[] = [];
  const hops = rng.randint(2, 4);
  for (let i = 0; i < hops; i++) {
    if (row - 1 < 3) break;
    row -= 1;
    items.push(["gap", 1]);
    items.push(["block", row, rng.randint(1, 2)]);
  }
  const plateau = rng.randint(3, 5);
  items.push(["gap", rng.randint(1, 2)]);
  items.push(["block", row, plateau]);
  if (cfg.platform_enemies && rng.random() < 0.4) items.push(["enemy_on_last", row]);

  const trap = startSurface === GROUND && rng.random() < 0.7;
  const before = b.columns.length;
  for (const item of items) {
    if (item[0] === "gap") b.gap(item[1]);
    else if (item[0] === "block") for (let i = 0; i < item[2]; i++) b.column(null, block(item[1]));
    else b.set(-2, item[1] - 1, "E");
  }
  if (trap) {
    const span = b.columns.length - before;
    for (let i = 0; i < Math.max(1, span - plateau - 3); i++) b.set(before + i, GROUND, "B");
  }
  b.gap(rng.randint(1, 2));
  b.surface = Math.min(GROUND, row + rng.randint(1, 4));
  b.flat(rng.randint(2, 4));
}

function highRoad(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  b.flat(2);
  const start = b.columns.length;
  let roadRow = GROUND;
  const items: [number, number | null][] = [];
  for (let i = 0; i < 3; i++) {
    roadRow -= 1;
    items.push([1, null]);
    items.push([rng.randint(1, 2), roadRow]);
  }
  const length = cfg.hard >= 3 ? rng.randint(40, 80) : rng.randint(20, cfg.hard >= 2 ? 70 : 35);
  let placed = 0;
  while (placed < length) {
    const gap = rng.randint(1, 2);
    const change = gap === 1 ? rng.choice([-1, 0, 0, 1]) : rng.choice([0, 0, 1]);
    roadRow = Math.max(4, Math.min(GROUND - 3, roadRow - change));
    const width = rng.randint(2, 4);
    items.push([gap, null]);
    items.push([width, roadRow]);
    placed += gap + width;
  }
  for (const [count, row] of items) for (let i = 0; i < count; i++) b.column(null, block(row));
  if (cfg.platform_enemies && rng.random() < 0.5) b.set(-2, roadRow - 1, "E");
  const end = b.columns.length;
  const stop = end - rng.randint(6, 9);
  for (let c = start; c < stop; c++) b.set(c, GROUND, "B");
  if (rng.random() < cfg.free_enemies) b.set(start + rng.randint(4, 10), GROUND - 1, "E");
  b.gap(rng.randint(1, 2));
  b.surface = Math.min(GROUND, roadRow + rng.randint(1, 3));
  b.flat(rng.randint(3, 5));
}

function tunnel(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  b.flat(2);
  const length = cfg.hard === 0 ? rng.randint(3, 4) : rng.randint(5, 9);
  const start = b.columns.length;
  for (let i = 0; i < length; i++) b.column(b.surface, [[b.surface - 2, "B"]]);
  if (cfg.hard >= 1) {
    const enemies = cfg.hard === 1 || rng.random() < 0.6 ? 1 : 2;
    for (const offset of rng.sample(range(2, length), Math.min(enemies, length - 2))) {
      b.set(start + offset, b.surface - 1, "E");
    }
  }
  b.flat(rng.randint(2, 3));
}

function shaft(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  const low = b.surface;
  for (let i = 0; i < 3; i++) {
    if (!b.rise()) break;
    b.flat(2);
  }
  b.flat(1);
  const fall = rng.randint(2, 3);
  const platformRow = Math.min(GROUND - 1, b.surface + fall);
  b.gap(cfg.hard === 0 ? rng.randint(1, 2) : rng.randint(2, 3));
  const width = cfg.hard === 0 ? 2 : cfg.hard === 1 ? rng.choice([1, 2]) : 1;
  for (let i = 0; i < width; i++) b.column(null, block(platformRow));
  b.gap(rng.randint(1, 2));
  b.surface = Math.max(platformRow, low);
  b.flat(rng.randint(2, 4));
}

function ceiling(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  const ceilingRow = b.surface - 3;
  const parts = cfg.hard === 0 ? rng.randint(1, 2) : rng.randint(2, 4);
  b.flat(1);
  for (let p = 0; p < parts; p++) {
    const n = rng.randint(2, 3);
    for (let i = 0; i < n; i++) b.column(b.surface, block(ceilingRow));
    const width = cfg.hard < 2 ? 1 : rng.randint(1, 2);
    for (let i = 0; i < width; i++) b.column(null, block(ceilingRow));
  }
  for (let i = 0; i < 2; i++) b.column(b.surface, block(ceilingRow));
  b.flat(2);
}

function twoRoutes(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  b.flat(2);
  const start = b.columns.length;
  let roadRow = GROUND;
  const items: [number, number | null][] = [];
  for (let i = 0; i < 3; i++) {
    roadRow -= 1;
    items.push([1, null]);
    items.push([rng.randint(1, 2), roadRow]);
  }
  const length = rng.randint(12, 24);
  let placed = 0;
  while (placed < length) {
    const gap = rng.randint(1, 2);
    if (gap === 1) roadRow = Math.max(5, Math.min(GROUND - 3, roadRow + rng.choice([-1, 0, 0, 1])));
    const width = rng.randint(2, 4);
    items.push([gap, null], [width, roadRow]);
    placed += gap + width;
  }
  for (const [count, row] of items) for (let i = 0; i < count; i++) b.column(GROUND, block(row));
  const end = b.columns.length;
  const n = cfg.free_enemies ? rng.randint(0, 2) : 0;
  for (let i = 0; i < n; i++) b.set(rng.randrange(start + 3, end - 1), GROUND - 1, "E");
  b.flat(rng.randint(2, 4));
}

function floating(b: Builder, row: number | null, count = 1, floor = false): void {
  for (let i = 0; i < count; i++) b.column(floor ? GROUND : null, block(row));
}

function rainStairs(b: Builder): void {
  const rng = b.rng;
  b.flat(2);
  let row = GROUND;
  const start = b.columns.length;
  const target = rng.randint(TOP_ROW + 1, 6);
  while (row > target) {
    row -= 1;
    floating(b, null, 1, true);
    const width = rng.randint(2, 4);
    const first = b.columns.length;
    floating(b, row, width, true);
    if (rng.random() < 0.8) {
      const c = first + rng.randrange(width);
      b.set(c, rng.randint(0, 1), "E");
    }
  }
  const step = rng.randint(3, 5);
  for (let c = start + 2; c < b.columns.length; c += step) {
    if (rng.random() < 0.5 && b.get(c, GROUND - 1) === " ") b.set(c, GROUND - 1, "E");
  }
  b.surface = row;
  b.waypoints.push([b.columns.length - 1, row]);
  b.flat(rng.randint(2, 4));
  b.waypoints.push([b.columns.length - 1, b.surface]);
}

function baitFork(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  b.flat(2);
  const start = b.columns.length;
  let roadRow = GROUND;
  const items: [number, number | null][] = [];
  for (let i = 0; i < 3; i++) {
    roadRow -= 1;
    items.push([1, null]);
    items.push([rng.randint(1, 2), roadRow]);
  }
  const length = rng.randint(14, 30);
  let placed = 0;
  while (placed < length) {
    const gap = rng.randint(1, 2);
    const change = gap === 1 ? rng.choice([-1, 0, 0]) : 0;
    roadRow = Math.max(5, Math.min(GROUND - 3, roadRow - change));
    const width = rng.randint(2, 4);
    items.push([gap, null]);
    items.push([width, roadRow]);
    placed += gap + width;
  }
  for (const [count, row] of items) for (let i = 0; i < count; i++) b.column(null, block(row));
  const end = b.columns.length;
  for (let r = Math.max(0, roadRow - 3); r < roadRow; r++) b.set(end - 1, r, "B");
  const pit = [end - 2, end - 1];
  for (let c = start; c < end; c++) if (!pit.includes(c)) b.set(c, GROUND, "B");
  if (rng.random() < cfg.free_enemies) b.set(start + rng.randint(3, 8), GROUND - 1, "E");
  b.waypoints.push([pit[0] - 1, GROUND]);
  b.surface = GROUND;
  b.flat(rng.randint(3, 5));
  b.waypoints.push([b.columns.length - 1, b.surface]);
}

function forkV10(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  const kind = rng.choice(["unten", "unten", "umkehren", "oben"]);
  b.flat(2);
  const start = b.columns.length;
  let roadRow = GROUND;
  const items: [number, number | null][] = [];
  for (let i = 0; i < 3; i++) {
    roadRow -= 1;
    items.push([1, null]);
    items.push([rng.randint(1, 2), roadRow]);
  }
  const length = rng.randint(14, 30);
  let placed = 0;
  while (placed < length) {
    const gap = kind === "umkehren" ? 0 : rng.randint(1, 2);
    const change = gap === 1 ? rng.choice([-1, 0, 0]) : 0;
    roadRow = Math.max(5, Math.min(GROUND - 3, roadRow - change));
    const width = rng.randint(2, 4);
    if (gap) items.push([gap, null]);
    items.push([width, roadRow]);
    placed += gap + width;
  }
  for (const [count, row] of items) for (let i = 0; i < count; i++) b.column(null, block(row));
  const end = b.columns.length;
  let floorEnd: number;
  if (kind === "oben") floorEnd = end - rng.randint(6, 8);
  else {
    floorEnd = end;
    for (let r = Math.max(0, roadRow - 3); r < roadRow; r++) b.set(end - 1, r, "B");
  }
  for (let c = start; c < floorEnd; c++) b.set(c, GROUND, "B");
  if (rng.random() < cfg.free_enemies) b.set(start + rng.randint(3, 8), GROUND - 1, "E");
  b.needsPath = true;
  b.stats["gabel_" + kind] = (b.stats["gabel_" + kind] ?? 0) + 1;
  if (kind === "oben") {
    b.waypoints.push([end - 1, roadRow]);
    b.surface = roadRow;
    b.flat(rng.randint(3, 5));
    b.waypoints.push([b.columns.length - 1, b.surface]);
    return;
  }
  b.waypoints.push([end - 1, GROUND - 1]);
  b.surface = GROUND;
  b.flat(rng.randint(3, 5));
  b.waypoints.push([b.columns.length - 1, b.surface]);
}

function channel(b: Builder, cfg: TierConfig, final = false): void {
  const rng = b.rng;
  const w = rng.randint(18, 30);
  const s = b.columns.length;
  const cols: string[][] = [];
  for (let c = 0; c < w; c++) cols.push(new Array<string>(ROWS).fill(" "));
  for (let c = 0; c < w; c++) cols[c][GROUND] = "B";
  for (let r = 0; r < 9; r++) cols[0][r] = "B";
  for (let c = 0; c < w - 4; c++) cols[c][8] = "B";
  for (const [c, top] of [[w - 4, 11], [w - 3, 10], [w - 2, 9]]) for (let r = top; r < GROUND; r++) cols[c][r] = "B";
  const rightTop = final ? 0 : 4;
  for (let r = rightTop; r < ROWS; r++) cols[w - 1][r] = "B";
  const enemies = cfg.free_enemies;
  if (rng.random() < enemies) cols[rng.randint(3, w - 7)][GROUND - 1] = "E";
  if (final) {
    const chest = rng.randint(1, 3);
    cols[chest][7] = "C";
    if (rng.random() < enemies) cols[rng.randint(chest + 4, w - 6)][7] = "E";
    b.stats["channel_end"] = (b.stats["channel_end"] ?? 0) + 1;
  } else {
    for (let c = 4; c < w - 1; c++) cols[c][4] = "B";
    for (const [c, top] of [[3, 7], [2, 6], [1, 5]]) for (let r = top; r < 8; r++) cols[c][r] = "B";
    if (rng.random() < enemies) cols[rng.randint(6, w - 6)][7] = "E";
    if (rng.random() < enemies) cols[rng.randint(6, w - 3)][3] = "E";
    if (w >= 22 && rng.random() < 0.4) {
      const h = rng.randint(8, w - 10);
      cols[h][8] = " ";
      if (rng.random() < 0.5) cols[h + 1][8] = " ";
    }
  }
  b.columns.push(...cols);
  b.needsPath = true;
  b.waypoints.push([s + w - 2, 8], [s + 4, 7]);
  if (final) return;
  b.waypoints.push([s + w - 2, 3]);
  b.surface = HIGHEST_SURFACE;
  b.flat(rng.randint(3, 5));
  b.waypoints.push([b.columns.length - 1, b.surface]);
}

function pipes(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  const base = b.surface;
  const n = rng.randint(2, 4);
  for (let i = 0; i < n; i++) {
    const width = rng.randint(2, 4);
    const start = b.columns.length;
    b.flat(width);
    if (i && width >= 3 && rng.random() < cfg.free_enemies + 0.2) b.set(start + Math.floor(width / 2), base - 1, "E");
    const height = base - 2 >= HIGHEST_SURFACE && rng.random() < 0.4 ? 2 : 1;
    if (height === 2) b.column(base - 1);
    for (let k = 0; k < 2; k++) b.column(base - height);
  }
  b.flat(rng.randint(2, 4));
}

function pyramid(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  const base = b.surface;
  const n = rng.randint(2, Math.min(4, base - HIGHEST_SURFACE));
  b.flat(2);
  for (let k = 1; k <= n; k++) b.column(base - k);
  b.column(base - n);
  if (rng.random() < 0.7) b.gap(rng.randint(1, 2));
  for (let k = n; k > 0; k--) b.column(base - k);
  const width = rng.randint(2, 4);
  b.flat(width, rng.random() < cfg.free_enemies);
}

function bridge(b: Builder): void {
  const rng = b.rng;
  const base = b.surface;
  b.flat(2);
  let row = base;
  for (let i = 0; i < 3; i++) {
    row -= 1;
    b.gap(1);
    b.column(null, block(row));
  }
  const length = rng.randint(6, 12);
  const start = b.columns.length;
  for (let i = 0; i < length; i++) b.column(null, block(row));
  const k = rng.randint(1, 2);
  for (const offset of rng.sample(range(2, length - 1), k)) b.set(start + offset, row - 1, "E");
  b.waypoints.push([b.columns.length - 1, row]);
  b.gap(1);
  b.surface = Math.min(GROUND, row + rng.randint(1, 3));
  b.flat(rng.randint(3, 5));
}

function enemyRamp(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  const n0 = rng.randint(2, 4);
  b.flat(n0, rng.random() < 0.5);
  let steps = 0;
  const stairs = rng.randint(3, 5);
  for (let i = 0; i < stairs; i++) {
    if (!b.rise()) break;
    steps += 1;
    const first = b.columns.length;
    const width = rng.randint(2, 4);
    b.flat(width);
    if (steps >= 2 && rng.random() < 0.25) b.set(first + width - 1, b.surface - 1, "E");
  }
  const top = rng.randint(5, 9);
  const first = b.columns.length;
  b.flat(top);
  const k = Math.min(top - 1, rng.randint(1, 3));
  for (const offset of rng.sample(range(1, top), k)) b.set(first + offset, b.surface - 1, "E");
  if (rng.random() < cfg.rain) {
    const c = first + rng.randrange(top);
    b.set(c, rng.randint(0, 1), "E");
  }
  b.waypoints.push([b.columns.length - 1, b.surface]);
}

function chain(b: Builder): void {
  const rng = b.rng;
  let row = b.surface;
  b.flat(1);
  let trend = rng.choice([-1, 0, 1]);
  const n = rng.randint(6, 14);
  for (let i = 0; i < n; i++) {
    if (rng.random() < 0.3) trend = rng.choice([-1, 0, 1]);
    let change = rng.random() < 0.7 ? trend : 0;
    const newRow = Math.max(TOP_ROW, Math.min(GROUND - 1, row + change));
    change = newRow - row;
    let gap = change < 0 ? rng.randint(1, 2) : rng.randint(1, 3);
    if (change < 0 && rng.random() < 0.3) gap = 3;
    const width = gap < 3 ? rng.choice([1, 2, 2]) : 2;
    b.gap(gap);
    row = newRow;
    floating(b, row, width);
  }
  b.waypoints.push([b.columns.length - 1, row]);
  if (row <= 6 && rng.random() < 0.4) {
    const landing = rng.randint(Math.max(row + 5, GROUND - 2), GROUND);
    b.gap(landing - row >= 7 ? rng.randint(3, 4) : 3);
    b.surface = landing;
  } else {
    b.gap(rng.randint(1, 2));
    b.surface = Math.max(row, Math.min(GROUND, row + rng.randint(0, 2)));
  }
  b.flat(rng.randint(2, 4));
  b.waypoints.push([b.columns.length - 1, b.surface]);
}

function trench(b: Builder): void {
  const rng = b.rng;
  b.flat(1);
  let row = b.surface;
  const plateau = rng.randint(TOP_ROW + 1, 5);
  while (row > plateau) {
    row -= 1;
    b.gap(1);
    floating(b, row, rng.randint(1, 2));
  }
  b.gap(rng.randint(1, 2));
  floating(b, row, rng.randint(2, 3));
  b.column(null, [[row, "B"], [row - 1, "B"]]);
  const width = rng.randint(5, 8);
  const first = b.columns.length;
  floating(b, row, width);
  const k = rng.randint(2, 3);
  for (const offset of rng.sample(range(1, width - 1), k)) b.set(first + offset, row - 1, "E");
  b.column(null, [[row, "B"], [row - 1, "B"]]);
  floating(b, row, rng.randint(2, 3));
  b.waypoints.push([b.columns.length - 1, row]);
  b.gap(rng.randint(1, 2));
  b.surface = Math.min(GROUND, row + rng.randint(1, 4));
  b.flat(rng.randint(2, 4));
  b.waypoints.push([b.columns.length - 1, b.surface]);
}

export interface JumpEntry {
  takeoff: number;
  gap: number;
  drop: number;
  landing: number;
}
export const JUMP_CATALOG = catalogJson as JumpEntry[];
const TIGHT = new Set(["4,0", "5,2"]);

let widest: Map<number, number> | null = null;
function widestGaps(): Map<number, number> {
  if (!widest) {
    widest = new Map();
    for (const e of JUMP_CATALOG) {
      if (!TIGHT.has(`${e.gap},${e.drop}`)) widest.set(e.drop, Math.max(widest.get(e.drop) ?? 0, e.gap));
    }
  }
  return widest;
}

function jumpSequence(b: Builder, cfg: TierConfig): void {
  const rng = b.rng;
  let row = b.surface;
  let width = 3;
  b.flat(2);
  const n = rng.randint(4, 10);
  for (let i = 0; i < n; i++) {
    const options: JumpEntry[] = [];
    const weights: number[] = [];
    for (const e of JUMP_CATALOG) {
      const land = row + e.drop;
      if (e.takeoff > width || !(TOP_ROW <= land && land <= GROUND)) continue;
      if (TIGHT.has(`${e.gap},${e.drop}`)) continue;
      let w = e.gap === widestGaps().get(e.drop) ? cfg.hard_jumps : 1.0;
      if (e.drop > 0 && land >= 9) w = 0.3;
      options.push(e);
      weights.push(w);
    }
    const e = rng.choiceWeighted(options, weights);
    b.gap(e.gap);
    row += e.drop;
    width = e.landing;
    const first = b.columns.length;
    for (let k = 0; k < width; k++) b.column(null, block(row));
    if (cfg.platform_enemies && width === 3 && rng.random() < 0.15) b.set(first + 1, row - 1, "E");
    b.waypoints.push([b.columns.length - 1, row]);
  }
  b.gap(rng.randint(1, 2));
  b.surface = Math.max(row, Math.min(GROUND, row + rng.randint(0, 2)));
  b.flat(rng.randint(2, 4));
  b.waypoints.push([b.columns.length - 1, b.surface]);
}

const EXAM_SKILL_BLOCKS = ["stones", "chain", "rain_stairs", "jump_seq", "enemy_ramp"];
const EXAM_SKILL_BOOST = 3.0;

/** Build a level of the given tier (0 .. NUM_TIERS-1). Variants as in Python ("v9" default, tier 13 is v10). */
export function generate(tierIndex: number, seed: number, variantIn = "v9"): GeneratedLevel {
  let variant = variantIn;
  const examSkills = variant === "pruefung";
  if (examSkills) variant = "v9";
  let cfg = TIERS[Math.max(0, Math.min(tierIndex, NUM_TIERS - 1))];
  if (tierIndex >= 13) variant = "v10";
  else if (tierIndex < 10) variant = "v9";
  else if (variant === "v10") cfg = { ...cfg, ...V10_EXTRA };
  const rng = new PyRandom(`${tierIndex}:${seed}`);
  const b = new Builder(rng);
  b.variant = variant;
  b.style = style(rng, cfg, variant);
  if (examSkills) {
    for (const kind of EXAM_SKILL_BLOCKS) {
      if (b.style.has(kind)) b.style.set(kind, b.style.get(kind)! * EXAM_SKILL_BOOST);
    }
  }
  b.flat(5);
  b.set(1, b.surface - 1, "P");
  if (examSkills && rng.random() < 0.6) {
    const n = rng.randint(2, 3);
    for (let i = 0; i < n; i++) {
      b.flat(rng.randint(2, 4));
      b.set(-1, rng.choice([0, 1, 2]), "E");
    }
  }
  if (cfg.start_enemies && rng.random() < 0.4) {
    b.flat(3);
    b.set(-1, rng.choice([b.surface - 1, 0, 1]), "E");
  }
  while (b.columns.length < cfg.length) {
    segment(b, cfg);
    const top = b.col(-1);
    if (top[b.surface] === "B" && b.surface > 0 && top[b.surface - 1] === " ") {
      b.waypoints.push([b.columns.length - 1, b.surface]);
    }
  }
  if (variant === "v10" && rng.random() < cfg.channel_end) {
    if (b.surface !== GROUND) {
      b.drop(GROUND - b.surface);
      b.flat(3);
    }
    channel(b, cfg, true);
  } else {
    b.flat(4);
    b.set(-2, b.surface - 1, "C");
    if (cfg.hard >= 3 && rng.random() < 0.5) {
      if (rng.random() < 0.6) {
        b.set(-2, b.surface - 1, " ");
        b.set(-1, b.surface - 1, "C");
      }
    } else {
      b.column(b.surface - 3);
    }
  }

  const lines: string[] = [];
  for (let r = 0; r < ROWS; r++) lines.push(b.columns.map((col) => col[r]).join("").replace(/\s+$/u, ""));
  const level = new Level(lines, `gen_t${tierIndex}_s${seed}`) as GeneratedLevel;
  level.buildingBlocks = { ...b.stats };
  const uniq = new Map<string, Cell>();
  for (const w of b.waypoints) uniq.set(`${w[0]},${w[1]}`, w);
  level.waypoints = [...uniq.values()].sort((p, q) => p[0] - q[0] || p[1] - q[1]);
  level.tier = tierIndex;
  level.variant = examSkills ? "pruefung" : variant;
  level.needsPath = b.needsPath;
  return level;
}
